#include <bits/stdc++.h>
using namespace std;

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int N, K;
    long long T;
    cin >> N >> K >> T;

    vector<int> P(N);
    for (int &p : P) cin >> p;

    vector<int> initial;
    for (int i = 0, g; i < N; ++i) {
        cin >> g;
        if (g == 1) initial.push_back(i);
    }

    const int INF = 1e9;
    const int maxScore = 9 * K;

    vector<vector<int>> prev(N, vector<int>(maxScore + 1, INF));
    for (int y = 0; y <= N - K; ++y) {
        prev[y][P[y]] = abs(initial[0] - y);
    }

    for (int j = 1; j < K; ++j) {
        vector<vector<int>> curr(N, vector<int>(maxScore + 1, INF));
        vector<int> prefixMin(9 * j + 1, INF);

        for (int y = j; y <= N - K + j; ++y) {
            int z = y - 1;
            for (int score = 0; score <= 9 * j; ++score) {
                prefixMin[score] = min(prefixMin[score], prev[z][score]);
            }

            int moveCost = abs(initial[j] - y);
            for (int score = 0; score <= 9 * j; ++score) {
                if (prefixMin[score] != INF) {
                    curr[y][score + P[y]] = prefixMin[score] + moveCost;
                }
            }
        }

        prev.swap(curr);
    }

    int answer = 0;
    for (int y = K - 1; y < N; ++y) {
        for (int score = 0; score <= maxScore; ++score) {
            if (prev[y][score] <= T) {
                answer = max(answer, score);
            }
        }
    }

    cout << answer << '\n';
    return 0;
}
